import * as React from 'react';
import * as CursorTooltipPrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface CursorTooltipProps extends React.ComponentPropsWithoutRef<typeof CursorTooltipPrimitive.CursorTooltip> {
  className?: string;
}

export const CursorTooltip = React.forwardRef<HTMLDivElement, CursorTooltipProps>(
  ({ className, children, ...props }, ref) => (
    <CursorTooltipPrimitive.CursorTooltip
      ref={ref}
      className={clsx(
        'relative inline-block cursor-pointer',
        className
      )}
      {...props}
    >
      {children}
    </CursorTooltipPrimitive.CursorTooltip>
  )
);
CursorTooltip.displayName = 'CursorTooltip';

